namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté garlic and ginger in butter.", "Add tomato sauce and simmer 10 minutes.", "Stir in cream and garam masala.", "Add chicken and simmer 5 more minutes."],
            AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Assemble tacos with beef and toppings."],
            AverageRating = 4.2, RatingCount = 8 },
        new() { Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = ["Spaghetti", "Guanciale", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water until al dente.", "Crisp guanciale in a pan.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with guanciale.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra pecorino."],
            AverageRating = 4.7, RatingCount = 15 },
        new() { Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste"],
            Steps = ["Soak rice noodles in warm water 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add noodles, fish sauce, and tamarind paste.", "Toss with shrimp, bean sprouts, and peanuts.", "Serve with lime wedges."],
            AverageRating = 4.4, RatingCount = 10 },
        new() { Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt"],
            Steps = ["Halve and pit avocados, scoop into bowl.", "Mash to desired consistency.", "Stir in diced onion, cilantro, and jalapeño.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
            AverageRating = 4.6, RatingCount = 18 },
        new() { Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = ["Coconut milk", "Green curry paste", "Chicken thighs", "Thai basil", "Bamboo shoots", "Fish sauce", "Sugar"],
            Steps = ["Heat coconut cream in a pot until oil separates.", "Fry curry paste until fragrant.", "Add chicken and cook 5 minutes.", "Pour in remaining coconut milk and bamboo shoots.", "Season with fish sauce and sugar.", "Simmer 15 minutes, finish with Thai basil."],
            AverageRating = 4.3, RatingCount = 7 },
        new() { Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = ["Chicken thighs", "Butter", "Tomato puree", "Cream", "Kasuri methi", "Garam masala", "Ginger-garlic paste"],
            Steps = ["Marinate chicken in yogurt and spices.", "Grill or bake chicken until cooked.", "Melt butter, sauté ginger-garlic paste.", "Add tomato puree and cook 15 minutes.", "Stir in cream, kasuri methi, and garam masala.", "Add chicken and simmer 10 minutes."],
            AverageRating = 4.9, RatingCount = 25 },
    ];

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void RateRecipe(int id, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == id);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void AddRecipe(string title, string ingredients, string steps, string category)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = category,
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        });
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="Rate @star star(s)">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.2s;
    }
    .star-rating .star.filled {
        color: #f5a623;
    }
    .star-rating .star:hover {
        color: #f5a623;
    }
    .rating-thanks {
        margin-left: 0.5rem;
        color: #28a745;
        font-size: 0.9rem;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _selectedRating;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _selectedRating = (int)Math.Round(CurrentRating);
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.RateRecipe(RecipeId, stars);
        _submitted = true;
    }
}

