    <p>No recipes found in this category.</p>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";
    private List<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (_recipe is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p>
        <span class="badge bg-secondary">@_recipe.Category</span>
        <span class="ms-2 text-warning">★</span> @_recipe.AverageRating / 5
        <small class="text-muted">(@_recipe.RatingCount ratings)</small>
    </p>

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="@_recipe.Id" CurrentRating="@_recipe.AverageRating" RatingCount="@_recipe.RatingCount" />

    <hr />

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>
}
else
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}

@code {
    [Parameter] public int Id { get; set; }
    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "<strong>@_title</strong>" has been submitted successfully.
        <a href="/">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_ingredients"
                placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_steps"
                placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = "";
    private string _category = "";
    private string _ingredients = "";
    private string _steps = "";
    private bool _submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(_title) &&
        !string.IsNullOrWhiteSpace(_category) &&
        !string.IsNullOrWhiteSpace(_ingredients) &&
        !string.IsNullOrWhiteSpace(_steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.AddRecipe(_title, _ingredients, _steps, _category);
        _submitted = true;
    }
}

